function makeSidebarPreviewEvents(){const rows=[['dot','Claimed pagination task'],['scout','Started export research'],['forge','Connected to workspace'],['dot','Saved search plan'],['scout','Renewed task lease'],['dot','Reviewed affected files'],['forge','Read project brief'],['scout','Finished export research'],['dot','Submitted review plan'],['forge','Checked file mappings'],['scout','Started CSV export'],['dot','Updated task notes']];const now=Date.now();return rows.map(([actor,summary],index)=>({actor,summary,at:new Date(now-(rows.length-1-index)*60_000).toISOString()})).reverse();}
