async function api(path,body){const response=await fetch(`/api/control/${path}`,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'content-type':'application/json','x-relay-client':'1'},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await response.json();if(!response.ok){const error=new Error(data.message||'Request failed');error.code=data.error;error.status=response.status;throw error;}return data;}
async function loadWorkspaceFiles(){try{const response=await fetch('/api/local/workspace-files',{cache:'no-store'});workspaceListing=response.ok?await response.json():null;}catch{workspaceListing=null;}}
async function refresh({quiet=false}={}){try{const before=JSON.stringify({...state,serverTime:null}),filesBefore=JSON.stringify(workspaceListing);state=await api('state');refreshTaskDagProjection();await loadWorkspaceFiles();const changed=before!==JSON.stringify({...state,serverTime:null})||filesBefore!==JSON.stringify(workspaceListing);if((!quiet||changed)&&!formDirty&&!activityPanelDrag&&!dialog.open&&!networkTransitioning&&!networkController?.isDragging()&&!document.querySelector('input:focus,textarea:focus,select:focus,[contenteditable=true]:focus'))render();}catch(e){if(e.code==='SETUP_REQUIRED'){state=await api('bootstrap',{});await loadWorkspaceFiles();render();}else if(!quiet)notify(e.message,true);}}
async function send(command,extra={},envelope=null){if((dialog.open&&taskDagMode==='demo'&&taskDagSelectedId)||(view==='tasks'&&dagDemoBoardActive)||(view==='portfolio'&&networkDemoActive())||hasDemoCommandTarget(command))throw new Error('Demo data stays in this browser. Switch to real data to make changes.');if(busy)return;const shown=command.taskId&&dialogSnapshot?.task.id===command.taskId?dialogSnapshot:null;if(shown&&dialogStale){throw new Error('Task changed. Reload before saving or approving.');}const shownProject=command.projectId&&projectSnapshot?.id===command.projectId?projectSnapshot:null;if(shownProject&&projectStale)throw new Error('Project changed. Reload before assigning.');busy=true;const t=shown?.task||(command.taskId?task(command.taskId):null);const request=envelope||{command,operationId:crypto.randomUUID(),epoch:shown?.epoch||state.meta.epoch,...(t?{expectedVersion:t.version}:{}),...(shownProject?{expectedProjectVersion:shownProject.version}:{}),...extra};document.querySelectorAll('button[type=submit],button[data-mutate]').forEach(b=>b.disabled=true);try{const next=await api('command',request);state=next;lastFailed=null;return next.result;}catch(e){lastFailed=e.status?null:request;if(shown&&['STALE_TASK','STALE_APPROVAL','STALE_EPOCH','STALE_HANDOFF','STALE_FENCE'].includes(e.code)){dialogStale=true;const content=dialog.querySelector('.dialog-content,.dialog-simple');content?.insertAdjacentHTML('afterbegin',`<div class="callout" role="alert"><strong>Task changed</strong><p>Reload before approving. Copy unsaved edits first.</p>${button('Reload task','reload-review',`data-id="${esc(shown.task.id)}"`,'primary')}</div>`);}if(shownProject&&e.code==='STALE_PROJECT'){projectStale=true;dialog.querySelector('.dialog-simple')?.insertAdjacentHTML('afterbegin',`<div class="callout" role="alert">Project changed. Copy unsaved edits before reloading. ${button('Reload project','reload-project',`data-id="${esc(shownProject.id)}"`)}</div>`);}notify(e.message+(dialogStale?' Reload the task.':''),true);if(e.status)await refresh({quiet:true});throw e;}finally{busy=false;document.querySelectorAll('button[type=submit],button[data-mutate]').forEach(b=>b.disabled=(dialogStale||projectStale)&&dialog.contains(b));}}
function matching(){return state.tasks.filter(t=>(!projectFilter||t.projectId===projectFilter)&&(!priority||t.priority===priority)&&(!hideDemo||!t.synthetic)&&(!query||`${t.title} ${t.id} ${t.component} ${t.description}`.toLowerCase().includes(query.toLowerCase())));}
function stats(){const real=state.tasks.filter(t=>!t.synthetic),agents=generalistAgents();return `<div class="stats"><div class="stat"><small>Active tasks</small><strong>${real.filter(t=>!['intake','ready'].includes(t.stage)).length}</strong><small>${real.length} tasks · ${state.tasks.filter(t=>t.synthetic).length} samples</small></div><div class="stat"><small>Awaiting approval</small><strong>${real.filter(t=>['plan_review','human_review'].includes(t.stage)).length}</strong><small>Plan or final approval</small></div><div class="stat"><small>Agents online</small><strong>${agents.filter(a=>['working','idle'].includes(a.status)).length}<span class="muted"> / ${agents.length}</span></strong><small>Heartbeat within 90 seconds</small></div><div class="stat"><small>Production ready</small><strong>${real.filter(t=>t.stage==='ready').length}</strong><small>Not deployed</small></div></div>`;}const ideIcon=(kind)=>{const paths={tasks:'M4 4h16v16H4z M4 9h16 M9 9v11',agents:'M8 8h8v9H8z M5 10H3v5h2 M19 10h2v5h-2 M12 4v4 M9 20h6',portfolio:'M4 5h6v6H4z M14 13h6v6h-6z M7 11v5h7',sites:'M3 5h18v14H3z M3 9h18 M7 7h.01 M10 7h.01',integrations:'M8 3v5 M16 3v5 M6 8h12v3a6 6 0 0 1-6 6v4 M6 8v3a6 6 0 0 0 6 6',back:'M14 6l-6 6 6 6',forward:'M10 6l6 6-6 6',search:'M16 16l5 5 M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',history:'M3 10a9 9 0 1 1 1 7 M3 4v6h6 M12 7v5l3 2',plus:'M12 5v14 M5 12h14',inbox:'M4 4h16v16H4z M4 13h5l1 3h4l1-3h5',review:'M9 12l2 2 4-5 M12 3l8 4v5c0 5-8 9-8 9s-8-4-8-9V7z',folder:'M3 6h7l2 2h9v12H3z',chevron:'M9 5l7 7-7 7',refresh:'M20 7v5h-5 M4 17v-5h5 M5 7a8 8 0 0 1 13-2l2 3 M4 16l2 3a8 8 0 0 0 13-2',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h1 M3 12h1 M3 18h1',board:'M4 4h6v16H4z M14 4h6v10h-6z',branch:'M6 3v12a4 4 0 0 0 4 4h8 M6 7h8a4 4 0 0 0 4-4',terminal:'M4 6l6 6-6 6 M13 18h7'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${`<path d="${paths[kind]||paths.tasks}"/>`}</svg>`;};
