  if(kind==='site-edit-request'){const draft=(state.siteDrafts||[]).find(item=>item.id===id),artifact=draft?.artifact;if(!draft||!artifact)throw Error('Record a local sample revision before queuing a request.');await send({type:'request_site_edit',draftId:id,request:values.request,elements:siteComposerState(draft).elements,artifactRevision:artifact.revision,artifactDigest:artifact.digest});siteEditorController?.destroy();siteEditorController=null;clearSiteComposer(draft);selectedSiteDraft=id;render();notify('Request saved for your site agent.');}
